<template><div class="filter-fields"><div class="filter-group"><div class="group-label"><span><AppIcon name="pin" :size="16" />位置范围</span></div><button class="location-button" @click="locationOpen = true"><span>{{ store.filters.locationName }}</span><AppIcon name="chevron" :size="15" /></button><div class="chips"><button v-for="radius in [1, 3, 5, 0]" :key="radius" class="chip" :class="{ active: store.filters.radius === radius }" @click="store.filters.radius = radius">{{ radius ? `${radius} km` : '不限' }}</button></div></div><div class="filter-group"><div class="group-label"><span><AppIcon name="ticket" :size="16" />人均预算</span></div><div class="chips"><button v-for="option in budgetOptions" :key="option.label" class="chip" :class="{ active: store.filters.minBudget === option.min && store.filters.maxBudget === option.max }" @click="setBudget(option.min, option.max)">{{ option.label }}</button><button class="chip" :class="{ active: customBudget }" @click="customBudget = !customBudget">自定义</button></div><div v-if="customBudget" class="custom-budget"><label>最低<input v-model.number="store.filters.minBudget" type="number" min="0" aria-label="最低人均预算" /></label><span>—</span><label>最高<input v-model.number="store.filters.maxBudget" type="number" min="0" aria-label="最高人均预算，零表示不限" /></label></div></div><div class="filter-group"><div class="group-label"><span><AppIcon name="fork" :size="16" />想吃哪一口</span></div><div class="chips"><button class="chip" :class="{ active: !store.filters.cuisines.length }" @click="store.filters.cuisines = []">都可以</button><button v-for="cuisine in cuisines" :key="cuisine" class="chip" :class="{ active: store.filters.cuisines.includes(cuisine) }" @click="toggleCuisine(cuisine)">{{ cuisine }}</button></div></div><div class="filter-group"><div class="group-label"><span><AppIcon name="heart" :size="16" />用餐场景</span><b class="soft">偏好</b></div><div class="chips"><button v-for="scene in scenes" :key="scene" class="chip" :class="{ active: store.filters.scene === scene }" @click="store.filters.scene = store.filters.scene === scene ? '' : scene">{{ scene }}</button></div><div class="preference-toggles"><label><span>偏好安静</span><input v-model="store.filters.quiet" type="checkbox" role="switch" aria-label="偏好安静环境" /></label><label><span>偏好清淡</span><input v-model="store.filters.mild" type="checkbox" role="switch" aria-label="偏好清淡口味" /></label></div></div><button class="more-fields" :aria-expanded="more" @click="more = !more"><AppIcon name="filter" :size="16" />人数、时间与饮食限制<AppIcon :name="more ? 'minus' : 'plus'" :size="16" /></button><div v-if="more" class="additional"><div class="field-row"><label class="field">用餐人数<input v-model.number="store.filters.people" type="number" min="1" max="20" /></label><label class="field">用餐时间<input v-model="store.filters.time" placeholder="今晚 19:30" /></label></div><label class="check-row"><input v-model="store.filters.noSpice" type="checkbox" />不能吃辣 <span>硬条件</span></label><div class="field">需要排除的过敏原<div class="allergy-options"><label v-for="allergen in [...new Set(['花生', '虾', '乳制品', '小麦', ...store.filters.allergies])]" :key="allergen"><input v-model="store.filters.allergies" type="checkbox" :value="allergen" />{{ allergen }}</label></div></div><div class="chips restriction-list"><button v-for="cuisine in store.filters.excludedCuisines" :key="cuisine" class="chip" @click="store.filters.excludedCuisines = store.filters.excludedCuisines.filter((item) => item !== cuisine)">不吃{{ cuisine }}<AppIcon name="close" :size="12" /></button><button v-for="ingredient in store.filters.avoidedIngredients" :key="ingredient" class="chip" @click="store.filters.avoidedIngredients = store.filters.avoidedIngredients.filter((item) => item !== ingredient)">不吃{{ ingredient }}<AppIcon name="close" :size="12" /></button></div><p v-if="store.filters.allergies.length" class="small muted">将排除菜品中出现该过敏原或资料不明的餐厅。成分由菜品信息推断，不能替代商家的饮食安全确认。</p></div><LocationPicker :open="locationOpen" @close="locationOpen = false" /></div></template>
<script setup lang="ts">
import { ref } from 'vue'
import { useDiningStore } from '@/stores/dining'
import { budgetOptions, cuisines, scenes } from '@/data/restaurants'
import AppIcon from './AppIcon.vue'
import LocationPicker from './LocationPicker.vue'
const store = useDiningStore(), more = ref(false), customBudget = ref(false), locationOpen = ref(false)
function setBudget(min: number, max: number) { store.filters.minBudget = min; store.filters.maxBudget = max; customBudget.value = false }
function toggleCuisine(c: string) { store.filters.excludedCuisines = store.filters.excludedCuisines.filter((item) => item !== c); store.filters.cuisines = store.filters.cuisines.includes(c) ? store.filters.cuisines.filter((v) => v !== c) : [...store.filters.cuisines, c] }
</script>
